import type { AgNumericValue } from 'ag-charts-types';
export declare function clamp(min: number, value: number, max: number): number;
/** Coerce a `number | bigint` to `number` for rendering maths; warns once when a bigint exceeds the Number range. */
export declare function toNumber(value: AgNumericValue): number;
/**
 * Like {@link toNumber} but accepts any value: bigints warn on out-of-range magnitudes, while all
 * other values keep raw `Number()` coercion semantics (`null` → 0, `undefined`/invalid → NaN).
 */
export declare function narrowToNumber(value: unknown): number;
/** Like {@link toNumber} but passes `null`/`undefined` through and stays silent on out-of-range magnitudes. */
export declare function toNumberOrUndefined(value: AgNumericValue | undefined): number | undefined;
/** Adds two operands, promoting to `bigint` when both are integral so a large-magnitude result stays exact. */
export declare function addValues(a: AgNumericValue, b: AgNumericValue): AgNumericValue;
/** Subtracts `b` from `a`, promoting to `bigint` under the same rules as {@link addValues}. */
export declare function subtractValues(a: AgNumericValue, b: AgNumericValue): AgNumericValue;
/** Smaller of two operands via comparison, preserving an exact `bigint` (`Math.min` throws on bigint). */
export declare function minValue(a: AgNumericValue, b: AgNumericValue): AgNumericValue;
/** Returns the larger of two operands, preserving an exact `bigint`. Mirror of {@link minValue}. */
export declare function maxValue(a: AgNumericValue, b: AgNumericValue): AgNumericValue;
/** Returns the absolute value, preserving an exact `bigint` rather than coercing. */
export declare function absValue(value: AgNumericValue): AgNumericValue;
/** Returns a zero of the same kind as `value` (`0n` for a `bigint`), keeping exact bigint arithmetic. */
export declare function zeroLike(value: AgNumericValue): AgNumericValue;
export declare function inRange(value: number, range: [number, number], epsilon?: number): boolean;
export declare function isNumberEqual(a: number, b: number, epsilon?: number): boolean;
export declare function isNegative(value: AgNumericValue): boolean;
export declare function isInteger(value: number): boolean;
export declare function roundTo(value: number, decimals?: number): number;
/** Drops the float noise of decimal arithmetic (e.g. 2.4999999999999716), so results compare by exact value. */
export declare function stripFloatNoise(value: number): number;
export declare function roundToMultiple(value: number, step: number): number;
export declare function ceilTo(value: number, decimals?: number): number;
/**
 * Returns the mathematically correct n modulus of m. For context, the JS % operator is remainder
 * NOT modulus, which is why this is needed.
 */
export declare function modulus(n: number, m: number): number;
export declare function countFractionDigits(value: number): number;
